dtsPropsFor.KpiTile:
label: string;
  value: string;
  unit?: string;
  context?: string;
  delta?: number | null;
  deltaLabel?: string;
  /** When set, the headline value itself is a trend metric: it gets the same ▲/▼ + pos/neg colour treatment as the delta chip, so all four tiles share one trend grammar. */
  valueTrend?: number | null;
  spark?: number[];
  /** CSS colour for the sparkline. Defaults to --orange on accent tiles, --teal otherwise. */
  sparkColor?: string;
  accent?: boolean;
  locale?: "en" | "fr";

dtsPropsFor.CoverageBar:
label: string;
  /** 0–1. Rendered as the filled proportion of the bar. */
  share: number;
  count: number;
  /** Localised word for "postings" — defaults to English. */
  postingsLabel?: string;
  locale?: "en" | "fr";

dtsPropsFor.Select:
label: string;
  value: string | undefined;
  /** First option is treated as the default; selecting any other one switches the control to its orange "narrowed" border. */
  options: { value: string; label: string; labelFr?: string; code?: string }[];
  onChange: (value: string) => void;
  id: string;
  /** Dark institutional treatment used by the Explore filter spine. */
  tone?: "light" | "dark";
